const items = $input.all();

// Datos que entraron originalmente en el nodo HTTP
const origenes = $('08A - Preparar URL Web').all();

return items.map((item, index) => {

  const datosError = item.json || {};

  // Intentar recuperar exactamente el prospecto que provocó el error
  let origen = datosError;

  if (!origen.row_number) {

    const paired = item.pairedItem;

    let indiceOriginal = null;

    if (Array.isArray(paired) && paired.length > 0) {
      indiceOriginal = paired[0]?.item;
    } else if (paired && typeof paired === 'object') {
      indiceOriginal = paired.item;
    }

    if (
      Number.isInteger(indiceOriginal) &&
      origenes[indiceOriginal]
    ) {
      origen = origenes[indiceOriginal].json;
    } else if (origenes[index]) {
      origen = origenes[index].json;
    }
  }

  // Obtener el mensaje de error devuelto por el HTTP Request
  const errorOriginal = String(
    datosError.error?.message ||
    datosError.message ||
    ''
  );

  let motivo =
    'No se pudo acceder automáticamente a la web.';

  if (/SSL/i.test(errorOriginal)) {

    motivo =
      'No se pudo acceder automáticamente a la web por un problema SSL.';

  } else if (/\b503\b/.test(errorOriginal)) {

    motivo =
      'La web respondió con error HTTP 503: temporalmente no disponible.';

  } else if (/\b403\b/.test(errorOriginal)) {

    motivo =
      'La web respondió con error HTTP 403: acceso bloqueado.';

  } else if (/\b404\b/.test(errorOriginal)) {

    motivo =
      'La web respondió con error HTTP 404: página no encontrada.';

  } else if (/\b429\b/.test(errorOriginal)) {

    motivo =
      'La web respondió con error HTTP 429: demasiadas solicitudes.';

  } else if (
    /timeout|timed out|ETIMEDOUT/i.test(errorOriginal)
  ) {

    motivo =
      'La web no respondió dentro del tiempo permitido.';

  }

  return {
    json: {
      row_number: origen.row_number || '',
      Empresa: origen.Empresa || '',
      Sector: origen.Sector || '',
      Ciudad: origen.Ciudad || '',
      Web: origen.Web || '',
      Email: origen.Email || '',
      'Teléfono': origen['Teléfono'] || '',

      'Estado Investigación': 'Revisión manual',

      'Motivo Revisión': motivo,

      'Acción Recomendada':
        'Revisar web manualmente antes de preparar propuesta comercial'
    },

    pairedItem: {
      item: index
    }
  };
});

const items = $input.all();

function limpiarHtml(html = '') {
  return String(html)
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<iframe[\s\S]*?<\/iframe>/gi, ' ')
    .replace(
      /<\/(p|div|section|article|h1|h2|h3|h4|h5|li|br|tr|td)>/gi,
      '\n'
    )
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();
}

return items.map((item, index) => {

  const html = String(item.json.data || '');
  const textoLimpio = limpiarHtml(html);

  // Recuperar el prospecto realmente vinculado a este resultado HTTP
  const origen = $('08A - Preparar URL Web')
    .itemMatching(index)
    .json;

  return {
    json: {
      row_number: origen.row_number || '',
      Empresa: origen.Empresa || '',
      Sector: origen.Sector || '',
      Ciudad: origen.Ciudad || '',
      Web: origen.Web || '',
      Email: origen.Email || '',
      'Teléfono': origen['Teléfono'] || '',

      'Contenido Web Limpio': textoLimpio.slice(0, 12000),

      'Longitud Contenido Original': html.length,

      'Longitud Contenido IA': Math.min(
        textoLimpio.length,
        12000
      ),

      'Estado Contenido Web':
        textoLimpio.length > 100
          ? 'Contenido preparado'
          : 'Contenido insuficiente'
    },

    pairedItem: {
      item: index
    }
  };
});

const items = $input.all();

return items.map(item => {
  let texto = String(item.json.text || '').trim();

  // Por seguridad, elimina posibles bloques ```json ... ```
  texto = texto
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    const analisis = JSON.parse(texto);

    return {
      json: {
        ...analisis,
        'Estado Parseo IA': 'Correcto'
      }
    };
  } catch (error) {
    return {
      json: {
        'Estado Parseo IA': 'Error',
        'Texto Original IA': texto,
        'Error Parseo IA': error.message
      }
    };
  }
});

const items = $input.all();

// Leemos las filas originales del CRM para conservar datos existentes
const crm = $('02 - Leer Prospectos del CRM')
  .all()
  .map(item => item.json);

// Fecha/hora de Madrid con formato del CRM
const fecha = new Date()
  .toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  })
  .replace(',', '');

// Prioridades válidas
const prioridadesValidas = new Set([
  'Alta',
  'Media',
  'Baja'
]);

return items.map(item => {
  const analisis = item.json;

  // Buscar la fila original exacta del CRM
  const original = crm.find(fila =>
    String(fila.row_number) === String(analisis.row_number)
  ) || {};

  // Conservar las notas anteriores
  const notasAnteriores = String(
    original.Notas || ''
  ).trim();

  // Crear bloque nuevo de análisis IA
  const bloqueIA = [
    `[Revisión comercial IA - ${fecha}]`,
    `Resumen: ${analisis.resumen_negocio || ''}`,
    `Oportunidad detectada: ${analisis.oportunidad_detectada || ''}`,
    `Evidencia web: ${analisis.evidencia_web || ''}`,
    `Motivo prioridad: ${analisis.motivo_prioridad || ''}`,
    `Ángulo de contacto: ${analisis.angulo_contacto || ''}`,
    `Acción recomendada: ${analisis.accion_recomendada || ''}`,
    `Estado revisión: ${analisis.estado_revision || 'Pendiente de revisión humana'}`
  ].join('\n');

  // Unir notas antiguas + nuevo análisis
  const notasFinales = notasAnteriores
    ? `${notasAnteriores}\n\n${bloqueIA}`
    : bloqueIA;

  // Validar prioridad devuelta por IA
  const prioridadIA = prioridadesValidas.has(
    analisis.prioridad_comercial
  )
    ? analisis.prioridad_comercial
    : (original.Prioridad || 'Media');

  return {
    json: {
      row_number: analisis.row_number,

      Empresa:
        analisis.empresa ||
        original.Empresa ||
        '',

      'Servicio recomendado':
        analisis.servicio_recomendado ||
        original['Servicio recomendado'] ||
        '',

      Prioridad: prioridadIA,

      Notas: notasFinales,

      'Fecha Actualización': fecha
    }
  };
});

